<?php
namespace Database\Seeders;
use App\Models\{CostCenter,ExpenseClaim,ExpensePolicy,JobBudget,Project,PurchaseRequest,User,Workspace,WorkspaceMember};use Illuminate\Database\Seeder;use Illuminate\Support\Facades\Schema;use Illuminate\Support\Str;
/** Provides phase20 finance seeder behavior within the WorkIntel application. */ class FinanceSeeder extends Seeder{/** Handles the run operation for the current WorkIntel workflow. */ public function run():void{if(!Schema::hasTable('expense_claims'))return;$w=Workspace::where('slug','acme-corp')->first();if(!$w)return;$owner=User::where('email','owner@acme.test')->first();$employee=User::where('email','employee@acme.test')->first();$em=$employee?WorkspaceMember::where('workspace_id',$w->id)->where('user_id',$employee->id)->first():null;if(!$em||!$owner)return;$cc=CostCenter::firstOrCreate(['workspace_id'=>$w->id,'code'=>'ENG'],['uuid'=>(string)Str::uuid(),'name'=>'Engineering','manager_member_id'=>$em->manager_id,'annual_budget'=>250000,'currency'=>$w->currency?:'USD','active'=>true]);$policy=ExpensePolicy::firstOrCreate(['workspace_id'=>$w->id,'name'=>'Standard Employee Expenses'],['uuid'=>(string)Str::uuid(),'status'=>'active','currency'=>$w->currency?:'USD','receipt_required_over'=>25,'mileage_rate'=>0.67,'daily_per_diem'=>75,'max_claim_amount'=>2500,'allowed_categories'=>['travel','meals','software','mileage','supplies'],'requires_approval'=>true,'created_by'=>$owner->id]);$project=Project::where('workspace_id',$w->id)->where('status','active')->first();$claim=ExpenseClaim::firstOrCreate(['workspace_id'=>$w->id,'claim_number'=>'EXP-2026-00001'],['uuid'=>(string)Str::uuid(),'member_id'=>$em->id,'project_id'=>$project?->id,'cost_center_id'=>$cc->id,'expense_policy_id'=>$policy->id,'title'=>'Client workshop travel','status'=>'draft','currency'=>$w->currency?:'USD','total_amount'=>0,'approved_amount'=>0,'reimbursement_status'=>'not_ready']);if($claim->items()->count()===0){$claim->items()->create(['expense_date'=>'2026-08-10','category'=>'mileage','description'=>'Travel to client workshop','amount'=>40.20,'tax_amount'=>0,'currency'=>$claim->currency,'mileage_km'=>60,'mileage_rate'=>0.67,'project_id'=>$project?->id,'cost_center_id'=>$cc->id]);$claim->update(['total_amount'=>40.20]);}if($project)JobBudget::firstOrCreate(['workspace_id'=>$w->id,'project_id'=>$project->id,'name'=>'Delivery Budget'],['uuid'=>(string)Str::uuid(),'cost_center_id'=>$cc->id,'currency'=>$project->currency?:$w->currency,'labor_budget'=>12000,'expense_budget'=>3000,'procurement_budget'=>2000,'alert_threshold_percent'=>80,'status'=>'active','start_date'=>$project->start_date,'end_date'=>$project->due_date,'created_by'=>$owner->id]);PurchaseRequest::firstOrCreate(['workspace_id'=>$w->id,'request_number'=>'PR-2026-00001'],['uuid'=>(string)Str::uuid(),'requester_member_id'=>$em->id,'project_id'=>$project?->id,'cost_center_id'=>$cc->id,'title'=>'Development testing devices','vendor'=>'Demo Vendor','currency'=>$w->currency?:'USD','amount'=>1200,'status'=>'draft','needed_by'=>'2026-08-25','justification'=>'Additional devices for cross-platform testing.','created_by'=>$employee->id]);}}
